/* Audiovisual workspace. AssetIndex remains the only script, material and revision store. */
(function () {
 'use strict';
 const key='nexus_story_workspace_v1',draftKey='nexus_story_drafts_v1';
 const read=(name,fallback)=>{try{return JSON.parse(localStorage.getItem(name)||'null')||fallback;}catch{return fallback;}};
 const saved=read(key,{}),drafts=read(draftKey,{});
 icons.story='<path d="M5 3h11l3 3v15H5zM9 8h6M9 12h6M9 16h4"/>';icons.flow='<rect x="3" y="4" width="18" height="16" rx="3"/><path d="m10 9 5 3-5 3z"/>';icons.editor='<path d="M3 4h18v6H3zM3 14h7v6H3zM14 14h7v6h-7z"/>';
 const S={projectId:saved.projectId||null,sceneId:saved.sceneId||null,shotId:saved.shotId||null,tab:saved.tab||'script',data:null,busy:false,loading:false,error:'',limit:80,query:'',materialScope:'project',type:'',inbox:false,chosen:false,mode:saved.mode||'proposal',scope:saved.scope||'fragment',preserve:new Set(saved.preserve||[]),selection:null,poll:null,dialog:null,linkAsset:null};
 const rows=(key)=>Array.isArray(S.data?.[key])?S.data[key]:[];
 const assets=()=>Agent.snapshot?.index?.assets?.filter(a=>!a.libraryDeleted)||[];
 const projects=()=>Agent.snapshot?.index?.projects?.filter(p=>!p.archived)||[];
 const scenes=()=>rows('scenes').sort((a,b)=>a.order-b.order);
 const shots=()=>rows('shots').sort((a,b)=>a.order-b.order);
 const blocks=()=>rows('blocks').sort((a,b)=>a.order-b.order);
 const title=(item)=>item?.title||item?.name||item?.code||item?.text?.slice(0,70)||'Sin título';
 const esc=value=>escape(value??'');
 const rid=()=>crypto.randomUUID();
 const status=value=>({pending:'Pendiente',prepared:'Preparado',generated:'Generado',chosen:'Elegido',idea:'Idea',story:'Incorporado',incorporated:'Incorporado',queued:'En cola',running:'En ejecución',pending_resume:'Pendiente de reanudación',waiting_approval:'Espera autorización',blocked:'Necesita información',complete:'Terminado',cancelled:'Cancelado',error:'Error'})[value]||value||'Pendiente';
 const role=value=>({identity:'Identidad',costume:'Vestuario',location:'Escenario',composition:'Encuadre',lighting:'Luz',sketch:'Boceto',generated:'Imagen generada',candidate:'Toma candidata',chosen:'Toma elegida',discarded:'Descartado',audio:'Audio',reference:'Referencia',output:'Resultado',final:'Material final',source:'Original'})[value]||'Referencia';
 const kind=value=>({action:'Acción',dialogue:'Diálogo',note:'Idea',reference:'Referencia',shot:'Plano',material:'Material',character:'Personaje',location:'Escenario',object:'Objeto',costume:'Vestuario',continuity:'Continuidad'})[value]||'Contenido';
 const scopeName=value=>({project:'Proyecto',scene:'Escena',shot:'Plano',block:'Fragmento',character:'Personaje',element:'Continuidad'})[value]||'Proyecto';
 const actionLabel=value=>({create_scene:'Añadir escena',update_scene:'Editar escena',move_scene:'Reordenar escena',delete_scene:'Retirar escena',create_shot:'Añadir plano',update_shot:'Editar plano',move_shot:'Mover plano',delete_shot:'Retirar plano',duplicate_shot:'Crear variante',create_block:'Insertar contenido',update_block:'Editar fragmento',move_block:'Mover fragmento',delete_block:'Retirar fragmento',update_project:'Actualizar historia',link_material:'Vincular material',unlink_material:'Retirar asociación',upsert_element:'Actualizar continuidad',set_preference:'Guardar indicación',import_script:'Importar guion'})[value]||'Actualizar proyecto';
 const labels={title:'Título',description:'Acción y descripción',text:'Texto',speaker:'Personaje que habla',group:'Acto o secuencia',code:'Identificador visible',intent:'Intención narrativa',framing:'Encuadre',camera:'Cámara y movimiento',performance:'Actuación',dialogue:'Diálogo',sound:'Sonido',duration_sec:'Duración orientativa',narrative_state:'Lugar en la historia',production_state:'Producción',scene_id:'Escena',character_ids:'Personajes presentes',name:'Nombre',aliases:'Otros nombres',variants:'Variantes de apariencia',notes:'Notas',kind:'Tipo de contenido',time_of_day:'Momento del día',light:'Luz',location_ids:'Escenarios',role:'Uso del material',asset_id:'Archivo',selected:'Material elegido',behavior:'Relación con referencias generales',enabled:'Indicación activa',order:'Posición',block_order:'Posición en el guion',synopsis:'Sinopsis',tone:'Tono e intención',visual_style:'Criterios visuales',treatment:'Tratamiento',format:'Formato',target_duration_sec:'Duración objetivo'};
 let draftsRestored=false;
 function persist(){const workspace={projectId:S.projectId,sceneId:S.sceneId,shotId:S.shotId,tab:S.tab,mode:S.mode,scope:S.scope,preserve:[...S.preserve]};try{localStorage.setItem(key,JSON.stringify(workspace));}catch{}if(typeof state==='object'){state.storyWorkspace=workspace;window.persist?.();}}
 function persistDrafts(){const buffers=Object.fromEntries(Object.entries(drafts).filter(([name,d])=>d.dirty||name.endsWith(':import')));const updatedAt=Date.now();try{localStorage.setItem(draftKey,JSON.stringify(buffers));localStorage.setItem(draftKey+':updatedAt',String(updatedAt));}catch{}if(typeof state==='object'){state.storyEditorDrafts=structuredClone(buffers);state.storyDraftsUpdatedAt=updatedAt;window.persist?.();}}
 function restoreDrafts(){if(draftsRestored||!initial)return;draftsRestored=true;let localAt=0;try{localAt=Number(localStorage.getItem(draftKey+':updatedAt')||0);}catch{}if(state.storyDraftsUpdatedAt>localAt){for(const name of Object.keys(drafts))delete drafts[name];Object.assign(drafts,state.storyEditorDrafts||{});}else for(const[name,d]of Object.entries(state.storyEditorDrafts||{}))if(!drafts[name])drafts[name]=d;const workspace=state.storyWorkspace;if(workspace&&!S.projectId){S.projectId=workspace.projectId||null;S.sceneId=workspace.sceneId||null;S.shotId=workspace.shotId||null;S.tab=workspace.tab||'script';S.mode=workspace.mode||'proposal';S.scope=workspace.scope||'fragment';S.preserve=new Set(workspace.preserve||[]);}}
 function draftId(type,id){return `${S.projectId}:${type}:${id}`;}
 function draft(type,item){const id=draftId(type,item.id),old=drafts[id];if(!old||!old.dirty&&old.base!==(item.revision||0))drafts[id]={base:item.revision||0,values:structuredClone(item),operation:rid()};return drafts[id];}
 function writeDraft(type,item,field,value){const d=draft(type,item);d.values[field]=value;d.operation=rid();persistDrafts();return d;}
 function discardDraft(type,id){delete drafts[draftId(type,id)];persistDrafts();}
 function stale(type,item){const value=drafts[draftId(type,item.id)];return value&&value.base!==(item.revision||0);}
 function allEntities(){return [...scenes(),...shots(),...blocks(),...rows('elements'),...rows('preferences')];}
 function named(id,fallback='Contenido'){return title(allEntities().find(item=>item.id===id)||projects().find(item=>item.id===id)||{name:fallback});}
 function mediaUrl(uri){return typeof uri==='string'&&(/^\/media\/[a-zA-Z0-9_.-]+$/.test(uri)||/^https:\/\//i.test(uri))?uri:null;}
 function preview(asset,large=false){const url=mediaUrl(asset?.uri);if(!url)return `<div class="story-no-media">${icon('library')}<span>${asset?'Original no disponible':'Sin material'}</span></div>`;if(asset.type==='IMAGE')return `<img src="${esc(url)}" loading="lazy" alt="${esc(asset.displayName)}">`;if(asset.type==='VIDEO'&&large)return `<video src="${esc(url)}" controls preload="metadata"></video>`;if(asset.type==='AUDIO'&&large)return `<audio src="${esc(url)}" controls preload="metadata"></audio>`;return `<div class="story-no-media"><span class="story-media-glyph">${asset.type==='VIDEO'?'▶':asset.type==='AUDIO'?'♫':'▤'}</span><span>${asset.type==='VIDEO'?'Vídeo':asset.type==='AUDIO'?'Audio':'Archivo'}</span></div>`;}
 async function call(op,args={}){const response=await rpc('agent',{op,args,owner:Agent.owner});const result=response.result??response;if(response.settings)Agent.settings=response.settings;if(result.index&&Agent.snapshot)Agent.snapshot.index=result.index;if(result.snapshot)Agent.snapshot=result.snapshot;if(Object.hasOwn(result,'selection')){S.selection=result.selection;if(Agent.snapshot)Agent.snapshot.storySelection=result.selection;}if(result.ok===false)throw Error(result.error||result.message||'No se pudo aplicar el cambio.');return result;}
 async function load(projectId=S.projectId,{paint=true}={}){
  if(S.loading)return;S.loading=true;
  try{await ensureAssistantReady();restoreDrafts();const id=projectId||S.projectId||Agent.snapshot.projectId||projects()[0]?.id;if(!id){S.projectId=null;S.data=null;return;}
   const result=await call('storyView',{projectId:id,sceneId:S.projectId===id&&scenes().some(s=>s.id===S.sceneId)?S.sceneId:null,shotId:S.projectId===id&&shots().some(s=>s.id===S.shotId)?S.shotId:null});
   if(S.projectId!==id){S.sceneId=null;S.shotId=null;}S.projectId=id;S.data=result.view||result;S.selection=result.selection||null;S.error='';
   if(!scenes().some(scene=>scene.id===S.sceneId))S.sceneId=scenes()[0]?.id||null;
   if(!shots().some(shot=>shot.id===S.shotId))S.shotId=null;persist();
  }catch(error){S.error=error.message;}finally{S.loading=false;if(paint&&view==='story')paintStory();}
 }
 async function mutate(input,{keepDialog=false,draftType=null,draftEntity=null}={}){
  if(S.busy)return;S.busy=true;S.error='';markBusy();
  const projectId=S.projectId,dialogAtStart=document.getElementById('story-dialog');const request={operation_id:rid(),...input};
  if(draftType&&draftEntity){const d=draft(draftType,draftEntity);request.operation_id=d.operation;request.expected_revision=d.base;}
  try{const result=await call('storyCommand',{projectId,input:request});if(draftType&&draftEntity)discardDraft(draftType,draftEntity.id);
   if(S.projectId===projectId){S.data=result.view||S.data;if(!keepDialog&&document.getElementById('story-dialog')===dialogAtStart)closeDialog();await load(projectId,{paint:false});if(view==='story')paintStory();}
   window.dispatchEvent(new CustomEvent('nexus:library-changed'));return result;
  }catch(error){S.error=error.message;const node=document.querySelector('#story-dialog-error');if(node)node.textContent=error.message;else toast(error.message);if(view==='story')paintStatus();throw error;}
  finally{S.busy=false;markBusy();}
 }
 function markBusy(){document.querySelectorAll('[data-story-mutate]').forEach(node=>node.disabled=S.busy||node.hasAttribute('data-story-conflict'));document.querySelectorAll('[data-story-saving]').forEach(node=>node.textContent=S.busy?'Guardando…':'Guardado');}
 function closeDialog(){const dialog=document.getElementById('story-dialog');if(dialog?.open)dialog.close();dialog?.remove();S.dialog=null;}
 function dialog(html,type){closeDialog();const node=document.createElement('dialog');node.id='story-dialog';node.className='story-dialog';node.innerHTML=html;document.body.append(node);S.dialog=type;node.addEventListener('close',()=>{S.dialog=null;node.remove();});node.addEventListener('click',event=>{if(event.target===node)closeDialog();});node.showModal();return node;}
 function button(action,text,extra=''){return `<button type="button" data-story="${action}" ${extra}>${text}</button>`;}
 function paintStatus(){const node=document.querySelector('[data-story-status]');if(node){node.textContent=S.error||'Guardado en el proyecto';node.classList.toggle('is-error',!!S.error);}}
 function renderSceneList(){return `<aside class="story-scenes"><div class="story-section-heading"><h2>Escenas</h2>${button('new-scene','+','title="Nueva escena" aria-label="Nueva escena"')}</div><div class="story-scenes-list">${scenes().map((scene,index)=>`<button class="story-scene ${scene.id===S.sceneId?'is-selected':''}" data-story-scene="${esc(scene.id)}"><span>${index+1}</span><div><strong>${esc(title(scene))}</strong>${scene.group?`<small>${esc(scene.group)}</small>`:''}</div></button>`).join('')}</div>${button('import-script','Importar guion')}${button('project','Historia y criterios')}${button('continuity','Personajes y continuidad')}${button('work','Trabajo y propuestas',`data-story-proposals="${rows('proposals').filter(p=>p.status==='pending'||p.status==='partial').length}"`)}</aside>`;}
 function insertion(order){return `<div class="story-insert" aria-label="Insertar contenido"><span>+</span>${[['action','Acción'],['dialogue','Diálogo'],['note','Idea'],['shot','Plano'],['reference','Referencia']].map(([value,label])=>`<button data-story-insert="${value}" data-story-order="${order}">${label}</button>`).join('')}</div>`;}
 function shotLinks(shot){return rows('links').filter(link=>link.scope==='shot'&&link.target_id===shot.id);}
 function cover(shot){const links=shotLinks(shot);const link=links.find(l=>l.selected)||links.find(l=>['generated','candidate','sketch','reference','chosen'].includes(l.role))||links[0];return assets().find(asset=>asset.id===link?.asset_id);}
 function shotCard(shot,board=false){return `<article class="story-shot ${S.shotId===shot.id?'is-selected':''}" data-story-shot-card="${esc(shot.id)}"><button class="story-shot-visual" data-story-edit="shot:${esc(shot.id)}" aria-label="Abrir ${esc(title(shot))}">${preview(cover(shot))}</button><div class="story-shot-copy"><div class="story-shot-kicker"><span>${esc(shot.code||'Plano')}</span><span>${esc(status(shot.narrative_state))} · ${esc(status(shot.production_state))}</span></div><button class="story-text-button story-shot-title" data-story-edit="shot:${esc(shot.id)}">${esc(title(shot))}</button>${shot.description?`<p>${esc(shot.description)}</p>`:''}${shot.variant_of?'<small>Variante</small>':''}<div class="story-row-actions">${button('shot-material','Material',`data-shot="${esc(shot.id)}"`)}${button('agent','Agente',`data-shot="${esc(shot.id)}"`)}${button('generate','ArtBox',`data-shot="${esc(shot.id)}"`)}${button('flow','Flow',`data-shot="${esc(shot.id)}"`)}<span class="story-push"></span>${button('move-shot','↑',`data-shot="${esc(shot.id)}" data-delta="-1" title="Subir plano" aria-label="Subir plano"`)}${button('move-shot','↓',`data-shot="${esc(shot.id)}" data-delta="1" title="Bajar plano" aria-label="Bajar plano"`)}</div></div></article>`;}
 function blockMarkup(block){const shot=shots().find(shot=>shot.id===block.shot_id);if(shot&&block.kind==='shot')return shotCard(shot);const d=draft('block',block),isStale=stale('block',block);return `<article class="story-block story-block-${esc(block.kind)}" data-story-block="${esc(block.id)}"><div class="story-block-heading"><span>${esc(kind(block.kind))}${block.narrative_state==='idea'?' · Por explorar':''}</span><span class="story-push"></span>${button('move-block','↑',`data-block="${esc(block.id)}" data-delta="-1" aria-label="Subir fragmento"`)}${button('move-block','↓',`data-block="${esc(block.id)}" data-delta="1" aria-label="Bajar fragmento"`)}${button('block-detail','···',`data-block="${esc(block.id)}" aria-label="Opciones del fragmento"`)}</div>${block.kind==='dialogue'?`<input class="story-speaker" data-story-block-field="speaker" data-id="${esc(block.id)}" value="${esc(d.values.speaker||'')}" aria-label="Personaje que habla" placeholder="Personaje">`:''}<textarea class="story-block-text" data-story-block-field="text" data-id="${esc(block.id)}" aria-label="${esc(kind(block.kind))}" rows="${Math.min(12,Math.max(3,String(d.values.text||'').split('\n').length+1))}" placeholder="${block.kind==='note'?'Escribe una idea…':'Escribe aquí…'}">${esc(d.values.text||'')}</textarea>${shot?`<div class="story-row-actions"><small>Nota original del plano</small><button type="button" data-story-edit="shot:${esc(shot.id)}">${esc(title(shot))}</button></div>`:''}${rows('links').filter(l=>l.scope==='block'&&l.target_id===block.id).length?`<div class="story-reference-strip">${rows('links').filter(l=>l.scope==='block'&&l.target_id===block.id).map(l=>{const a=assets().find(a=>a.id===l.asset_id);return `<button data-story-asset="${esc(l.asset_id)}" title="${esc(a?.displayName||'Material')}">${preview(a)}</button>`;}).join('')}</div>`:''}<div class="story-row-actions"><span class="story-draft-note ${isStale?'is-error':''}">${isStale?'Hay una edición más reciente. Tu borrador se conserva.':drafts[draftId('block',block.id)]?.dirty?'Borrador guardado en este PC':'Texto del proyecto'}</span><span class="story-push"></span>${button('block-material','Referencia',`data-block="${esc(block.id)}"`)}${button('agent','Agente',`data-block="${esc(block.id)}"`)}${isStale?button('compare-block','Comparar',`data-block="${esc(block.id)}"`):button('save-block','Guardar',`data-block="${esc(block.id)}" data-story-mutate`)}</div></article>`;}
 function renderScript(){const scene=scenes().find(s=>s.id===S.sceneId);if(!scene)return `<div class="story-empty"><h2>Empieza con una escena</h2><p>Una frase, una imagen o un guion completo. La historia puede seguir cambiando mientras trabajas.</p>${button('new-scene','Crear escena','class="primary"')}</div>`;const list=blocks().filter(b=>b.scene_id===scene.id),legacy=shots().filter(s=>s.scene_id===scene.id&&!list.some(b=>b.shot_id===s.id));return `<section class="story-script"><div class="story-scene-heading"><div>${scene.group?`<p class="story-kicker">${esc(scene.group)}</p>`:''}<h2>${esc(title(scene))}</h2>${scene.description?`<p>${esc(scene.description)}</p>`:''}</div><div class="story-row-actions">${button('edit-scene','Editar escena')}${button('scene-material','Referencias')}${button('agent','Agente')}${button('move-scene','←',`data-delta="-1" aria-label="Mover escena antes"`)}${button('move-scene','→',`data-delta="1" aria-label="Mover escena después"`)}</div></div>${insertion(0)}${list.slice(0,S.limit).map(b=>blockMarkup(b)+insertion(b.order+1)).join('')}${list.length>S.limit?button('more',`Mostrar ${Math.min(80,list.length-S.limit)} fragmentos más`):''}${legacy.map(s=>shotCard(s)).join('')}</section>`;}
 function renderBoard(){const list=shots().filter(s=>!S.sceneId||s.scene_id===S.sceneId);return `<section class="story-board-wrap"><div class="story-section-heading"><h2>${list.length} planos</h2>${button('new-shot','+ Plano','class="primary"')}</div><div class="story-board">${list.slice(0,S.limit).map(s=>shotCard(s,true)).join('')}</div>${!list.length?'<div class="story-empty"><p>Añade el primer plano a esta escena.</p></div>':''}${list.length>S.limit?button('more','Mostrar más planos'):''}</section>`;}
 function materialList(){const linkIds=new Set(rows('links').map(l=>l.asset_id));const targets=new Set(S.materialScope==='scene'?[S.sceneId,...shots().filter(s=>s.scene_id===S.sceneId).map(s=>s.id),...blocks().filter(b=>b.scene_id===S.sceneId).map(b=>b.id)]:S.materialScope==='shot'?[S.shotId]:S.materialScope.startsWith('character:')?[S.materialScope.slice(10)]:[]);const query=S.query.toLocaleLowerCase();return assets().filter(a=>(S.materialScope==='all'||a.projectId===S.projectId||linkIds.has(a.id))&&(!targets.size||rows('links').some(l=>l.asset_id===a.id&&targets.has(l.target_id)))&&(!S.inbox||!linkIds.has(a.id)&&a.projectId===S.projectId)&&(!S.chosen||rows('links').some(l=>l.asset_id===a.id&&l.selected))&&(!S.type||a.type===S.type)&&(!query||[a.displayName,...a.tags||[],...rows('links').filter(l=>l.asset_id===a.id).map(l=>role(l.role))].join(' ').toLocaleLowerCase().includes(query))).sort((a,b)=>b.createdAt-a.createdAt);}
 function renderMaterial(){const list=materialList();return `<section class="story-material"><div class="story-material-filters"><input id="story-material-search" type="search" placeholder="Buscar por nombre, etiqueta o uso" aria-label="Buscar material" value="${esc(S.query)}"><select id="story-material-scope" aria-label="Contexto del material">${[['project','Proyecto'],['scene','Escena'],['shot','Plano seleccionado'],['all','Toda la biblioteca'],...rows('elements').filter(e=>e.kind==='character').map(c=>['character:'+c.id,c.name])].map(([value,label])=>`<option value="${esc(value)}" ${S.materialScope===value?'selected':''}>${esc(label)}</option>`).join('')}</select><select id="story-material-type" aria-label="Tipo de archivo">${[['','Todos los tipos'],['IMAGE','Imágenes'],['VIDEO','Vídeos'],['AUDIO','Audio'],['OTHER','Documentos']].map(([v,l])=>`<option value="${v}" ${S.type===v?'selected':''}>${l}</option>`).join('')}</select><label class="story-check"><input type="checkbox" id="story-material-inbox" ${S.inbox?'checked':''}>Por colocar</label><label class="story-check"><input type="checkbox" id="story-material-chosen" ${S.chosen?'checked':''}>Elegido</label>${button('import-material','Importar','class="primary"')}</div><div class="story-material-grid">${list.slice(0,S.limit).map(a=>`<button class="story-material-tile" data-story-asset="${esc(a.id)}"><span class="story-material-visual">${preview(a)}</span><strong>${esc(a.displayName)}</strong><small>${rows('links').filter(l=>l.asset_id===a.id).length} usos</small></button>`).join('')}</div>${!list.length?'<div class="story-empty"><p>No hay material con estos filtros.</p></div>':''}${list.length>S.limit?button('more','Mostrar más archivos'):''}<input type="file" id="story-media-picker" multiple hidden></section>`;}
 function renderContext(){return `<div class="story-agent-context"><label>Agente<select id="story-agent-mode"><option value="proposal" ${S.mode==='proposal'?'selected':''}>Proponer</option><option value="direct" ${S.mode==='direct'?'selected':''}>Cambios directos</option></select></label><label>Alcance<select id="story-agent-scope"><option value="fragment" ${S.scope==='fragment'?'selected':''}>Selección</option><option value="scene" ${S.scope==='scene'?'selected':''}>Escena</option><option value="project" ${S.scope==='project'?'selected':''}>Proyecto</option></select></label>${button('preserve',`${S.preserve.size?S.preserve.size+' fijados':'Conservar planos'}`)}<span class="story-push"></span><span data-story-status role="status" class="${S.error?'is-error':''}">${esc(S.error||'Guardado en el proyecto')}</span>${button('undo','Deshacer','data-story-mutate title="Deshacer último cambio"')}${button('refresh','Actualizar','title="Recuperar cambios del agente"')}</div>`;}
 function paintStory(){if(view!=='story')return;const content=$('#content');content.classList.add('story-view');$('#title').textContent='Guion';$('#eyebrow').textContent='NEXUS · PROYECTO AUDIOVISUAL';$('#header-actions').innerHTML='';if(!Agent.snapshot){content.innerHTML=S.error?`<div class="story-empty"><h2>No se pudo abrir el proyecto</h2><p role="alert">${esc(S.error)}</p>${button('refresh','Volver a conectar','class="primary"')}</div>`:'<div class="story-empty"><span class="loading"></span><p>Abriendo tus proyectos…</p></div>';if(!S.error&&!S.loading)load();return;}content.innerHTML=`<div class="story-project-bar"><select id="story-project" aria-label="Proyecto audiovisual"><option value="">Selecciona un proyecto</option>${projects().map(p=>`<option value="${esc(p.id)}" ${p.id===S.projectId?'selected':''}>${esc(p.name)}</option>`).join('')}</select>${button('new-project','+ Proyecto')}${S.projectId?`<nav class="story-view-tabs" aria-label="Vistas del proyecto">${[['script','Guion'],['board','Storyboard'],['material','Material']].map(([id,label])=>`<button data-story-tab="${id}" aria-current="${S.tab===id?'page':'false'}" class="${S.tab===id?'active':''}">${label}</button>`).join('')}</nav>`:''}</div>${S.projectId&&S.data?renderContext()+`<div class="story-layout">${renderSceneList()}<div class="story-main">${S.tab==='board'?renderBoard():S.tab==='material'?renderMaterial():renderScript()}</div></div>`:`<div class="story-empty"><h2>Tu historia y su material, juntos</h2><p>Abre un proyecto o crea uno. Guion, storyboard y biblioteca compartirán la misma estructura.</p>${button('new-project','Crear proyecto','class="primary"')}${S.error?`<p role="alert">${esc(S.error)}</p>`:''}</div>`}`;markBusy();}
 function field(name,label,value='',multiline=false,extra=''){return `<label>${label}${multiline?`<textarea name="${name}" rows="${name==='text'?8:3}" ${extra}>${esc(value)}</textarea>`:`<input name="${name}" value="${esc(value)}" ${extra}>`}</label>`;}
 function formShell(titleText,body,actions=''){return `<header><h2>${esc(titleText)}</h2>${button('close-dialog','×','aria-label="Cerrar conservando borrador"')}</header><div class="story-dialog-body">${body}<p id="story-dialog-error" class="story-error" role="alert"></p></div><footer>${actions}</footer>`;}
 function entityForm(type,item=null,order=null){const entity=item||{id:'new:'+type+':'+(S.sceneId||'project'),revision:0,scene_id:S.sceneId};const d=draft(type,entity),v=d.values,isNew=!item;S.dialogEntity={type,entity,isNew,order};let body='';if(type==='scene'){body=field('title','Título',v.title)+field('description','Situación e intención',v.description,true)+field('group','Acto, secuencia o capítulo · opcional',v.group)+field('time_of_day','Momento del día · opcional',v.time_of_day)+field('light','Luz · opcional',v.light);}else if(type==='shot'){body=field('title','Título del plano',v.title)+field('description','Qué ocurre',v.description,true)+field('intent','Qué debe contar',v.intent,true)+`<fieldset><legend>Personajes presentes</legend>${rows('elements').filter(c=>c.kind==='character').map(c=>`<label class="story-check"><input type="checkbox" name="character_ids" value="${esc(c.id)}" ${(v.character_ids||[]).includes(c.id)?'checked':''}>${esc(c.name)}</label>`).join('')||'<p class="hint">Añádelos en Personajes y continuidad.</p>'}</fieldset><div class="story-fields-inline"><label>Lugar en la historia<select name="narrative_state"><option value="story" ${v.narrative_state!=='idea'?'selected':''}>Incorporado</option><option value="idea" ${v.narrative_state==='idea'?'selected':''}>Idea</option></select></label><label>Producción<select name="production_state">${['pending','prepared','generated','chosen'].map(value=>`<option value="${value}" ${v.production_state===value?'selected':''}>${status(value)}</option>`).join('')}</select></label></div><details><summary>Cámara, actuación, sonido y duración</summary>${[['framing','Encuadre'],['camera','Cámara y movimiento'],['performance','Actuación'],['dialogue','Diálogo'],['sound','Sonido'],['duration_sec','Duración orientativa · segundos']].map(([name,label])=>field(name,label,v[name]??'',name!=='duration_sec',name==='duration_sec'?'type="number" min="0.1" step="any"':'')).join('')}</details>`;}else{body=field('text',v.kind==='note'?'Idea':'Texto',v.text,true)+(v.kind==='dialogue'?field('speaker','Personaje que habla',v.speaker):'')+`<label>Lugar en la historia<select name="narrative_state"><option value="story" ${v.narrative_state!=='idea'?'selected':''}>Incorporado</option><option value="idea" ${v.narrative_state==='idea'?'selected':''}>Idea por explorar</option></select></label>`;}
  if(type!=='scene')body+=`<label>Escena<select name="scene_id">${scenes().map(s=>`<option value="${esc(s.id)}" ${v.scene_id===s.id?'selected':''}>${esc(title(s))}</option>`).join('')}</select></label>`;
  if(!isNew&&type==='shot')body+=`<section class="story-effective-refs"><h3>Referencias efectivas</h3>${rows('effective_references').length?`<div class="story-reference-strip">${rows('effective_references').map(link=>`<button type="button" data-story-asset="${esc(link.asset_id)}" title="${esc(role(link.role)+' · '+scopeName(link.scope))}">${preview(assets().find(a=>a.id===link.asset_id))}</button>`).join('')}</div><p class="hint">${rows('effective_references').map(l=>esc(role(l.role)+' · '+scopeName(l.scope)+(l.behavior==='replace'?' · sustituye generales':''))).join(' / ')}</p>`:'<p class="hint">Sin referencias asignadas a este contexto.</p>'}</section>`;
  const conflict=stale(type,entity);if(conflict)body=`<div class="story-conflict"><strong>Hay una edición más reciente.</strong><p>Tu borrador sigue aquí. Compara antes de guardar.</p>${button('compare-dialog','Comparar revisión')}</div>`+body;
  const node=dialog(formShell(isNew?`Añadir ${type==='scene'?'escena':type==='shot'?'plano':kind(v.kind).toLowerCase()}`:title(item),`<form id="story-entity-form">${body}</form>`,`<span class="story-draft-note">Borrador guardado en este PC</span><span class="story-push"></span>${!isNew?button('delete-entity','Eliminar','class="story-danger" data-story-mutate'):''}${!isNew&&type==='shot'?button('duplicate-entity','Crear variante','data-story-mutate'):''}${!isNew?button('entity-material','Material'):''}${button('save-entity','Guardar',`class="primary" data-story-mutate ${conflict?'disabled data-story-conflict':''}`)}`),'entity');node.dataset.draftId=draftId(type,entity.id);node.querySelectorAll('#story-entity-form input,#story-entity-form textarea,#story-entity-form select').forEach(input=>input.addEventListener('input',()=>saveEntityDraft()));return node;
 }
 function saveEntityDraft(){if(!S.dialogEntity)return;const {type,entity}=S.dialogEntity,form=document.querySelector('#story-entity-form');if(!form)return;const values=Object.fromEntries(new FormData(form));if(type==='shot'){values.character_ids=[...form.querySelectorAll('[name="character_ids"]:checked')].map(input=>input.value);if(values.duration_sec==='')values.duration_sec=null;else values.duration_sec=Number(values.duration_sec);}const d=draft(type,entity);d.values={...d.values,...values};d.dirty=true;d.operation=rid();persistDrafts();}
 function scenePicker(type){const list=type==='shot'?shots():scenes();return list.find(item=>item.id===(type==='shot'?S.shotId:S.sceneId));}
 async function selectContext({shotId=null,blockId=null,navigateAgent=true}={}){if(!S.projectId)return;const shot=shots().find(s=>s.id===shotId),block=blocks().find(b=>b.id===blockId);const sceneId=shot?.scene_id||block?.scene_id||S.sceneId;const selection={projectId:S.projectId,sceneId:S.scope==='project'?null:sceneId,shotId:S.scope==='fragment'?shotId:null,blockId:S.scope==='fragment'?blockId:null,mode:S.mode,preserveIds:[...S.preserve]};await call('storySelection',selection);S.selection=selection;S.shotId=shotId;persist();if(navigateAgent){await agentCall('project',{id:S.projectId});navigate('assistant');decorateAgentContext();}return selection;}
 function decorateAgentContext(){document.querySelector('.story-chat-context')?.remove();const selection=Agent.snapshot?.storySelection??S.selection;if(!selection||!document.querySelector('#agent-compose')||Agent.snapshot?.projectId!==selection.projectId)return;const node=document.createElement('div');node.className='story-chat-context';node.innerHTML=`<div><strong>${esc([named(selection.projectId,'Proyecto'),selection.sceneId?named(selection.sceneId,'Escena'):null,selection.shotId?named(selection.shotId,'Plano'):null].filter(Boolean).join(' › '))}</strong><small>${selection.mode==='direct'?'Cambios directos':'Propuestas'} · ${selection.blockId?'fragmento':selection.shotId?'plano':selection.sceneId?'escena':'proyecto'}${selection.preserveIds.length?' · '+selection.preserveIds.length+' fijados':''}</small></div>${button('return-story','Abrir guion')}${button('clear-context','×','aria-label="Quitar contexto audiovisual"')}`;document.querySelector('#agent-compose').before(node);}
 function linkDialog(scope,targetId,assetId=null){S.linkTarget={scope,targetId};S.linkAsset=assetId;const characters=rows('elements').filter(e=>e.kind==='character');dialog(formShell('Vincular material',`<p class="hint">Un mismo archivo puede tener varios usos. Aquí eliges el suyo en ${esc(named(targetId,scopeName(scope)))}.</p><form id="story-link-form"><label>Uso<select name="role">${['reference','identity','costume','location','composition','lighting','sketch','generated','candidate','audio','chosen','discarded'].map(r=>`<option value="${r}">${role(r)}</option>`).join('')}</select></label><label>Personaje · para identidad o vestuario<select name="character_id"><option value="">Sin personaje específico</option>${characters.map(c=>`<option value="${esc(c.id)}" ${scope==='character'&&targetId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label>Referencias generales<select name="behavior"><option value="complement">Complementar</option><option value="replace">Sustituir las del mismo tipo y personaje</option></select></label><label class="story-check"><input type="checkbox" name="selected">Elegido en este contexto</label><input id="story-link-search" type="search" placeholder="Buscar archivo" aria-label="Buscar archivo"></form><div class="story-link-grid">${assets().map(a=>`<button type="button" data-story-link-asset="${esc(a.id)}" class="${a.id===assetId?'is-selected':''}" data-name="${esc(a.displayName.toLocaleLowerCase())}">${preview(a)}<span>${esc(a.displayName)}</span></button>`).join('')}</div>`,button('apply-link','Vincular','class="primary" data-story-mutate')),'link');}
 function assetDialog(assetId){const asset=assets().find(a=>a.id===assetId);if(!asset)return;const links=rows('links').filter(l=>l.asset_id===assetId);dialog(formShell(asset.displayName,`<div class="story-asset-preview">${preview(asset,true)}</div><p>${links.length?links.length+' usos · un único archivo':'Por colocar · sin asociaciones'}</p>${links.map(link=>`<div class="story-asset-use"><div><strong>${esc(named(link.target_id,scopeName(link.scope)))}</strong><small>${esc(role(link.role))}${link.selected?' · Elegido':''}${link.stale?' · Revisar contexto':''}</small></div>${button('unlink','Quitar vínculo',`data-link="${esc(link.id)}" data-revision="${link.revision}" data-story-mutate`)}</div>`).join('')}<details><summary>Origen</summary><p>${asset.source==='GENERATED'?'Generado':asset.source==='SHARED'?'Compartido':'Importado'}${asset.createdAt?' · '+new Date(asset.createdAt).toLocaleString('es'):''}</p>${asset.generationId?'<p>Conserva su generación de origen en la biblioteca.</p>':''}</details>`,`${mediaUrl(asset.uri)?`<a href="${esc(asset.uri)}" download="${esc(asset.displayName)}" target="_blank" rel="noopener">Descargar original</a>`:''}<span class="story-push"></span>${button('reuse-material','Vincular a la selección',`data-asset="${esc(asset.id)}" class="primary"`)}`),'asset');}
 function prettyValue(field,value){if(value==null||value==='')return 'Sin definir';if(field==='scene_id')return named(value,'Escena');if(field==='asset_id')return assets().find(a=>a.id===value)?.displayName||'Archivo';if(['character_ids','location_ids'].includes(field))return (value||[]).map(id=>named(id,field==='character_ids'?'Personaje':'Escenario')).join(', ')||'Ninguno';if(field==='narrative_state'||field==='production_state')return status(value);if(field==='role')return role(value);if(field==='kind')return kind(value);if(typeof value==='boolean')return value?'Sí':'No';if(field==='behavior')return value==='replace'?'Sustituye generales':'Complementa generales';if(field==='order'||field==='block_order')return String(Number(value)+1);if(field.endsWith('_sec'))return `${value} s`;return Array.isArray(value)?value.join(', '):String(value);}
 function proposalDialog(id){const p=rows('proposals').find(p=>p.id===id);if(!p)return;const remaining=p.changes.filter(c=>!(p.applied_ids||[]).includes(c.id));S.proposalId=id;dialog(formShell(p.title,`<p class="hint">Cada cambio conserva su revisión base. Una edición reciente nunca se sustituye sin comprobarla.</p>${remaining.map(entry=>{const cmd=entry.command,current=allEntities().find(x=>x.id===(cmd.shot_id||cmd.block_id||cmd.scene_id||cmd.element_id)),fields=Object.keys(cmd).filter(k=>labels[k]);return `<section class="story-proposal-change"><label class="story-check"><input type="checkbox" data-story-change="${esc(entry.id)}" checked><strong>${esc(actionLabel(cmd.action))}${current?' · '+esc(title(current)):''}</strong></label>${fields.map(field=>`<div class="story-diff-field"><strong>${labels[field]}</strong>${current&&Object.hasOwn(current,field)?`<div class="story-diff-old"><small>Actual</small><p>${esc(prettyValue(field,current[field]))}</p></div>`:''}<div class="story-diff-new"><small>Propuesta</small><p>${esc(prettyValue(field,cmd[field]))}</p></div></div>`).join('')||'<p>Se actualizará la organización de este contenido.</p>'}</section>`;}).join('')}`,`${button('reject-proposal','Descartar','data-story-mutate')}<span class="story-push"></span>${button('apply-proposal','Aplicar selección','class="primary" data-story-mutate')}`),'proposal');}
 function workDialog(){const a=S.data?.autonomy||{};dialog(formShell('Trabajo y propuestas',`<form id="story-autonomy-form"><label class="story-check"><input type="checkbox" name="enabled" ${a.enabled?'checked':''}>Preparación habilitada</label><label>Modo<select name="mode">${[['preparation','Preparar'],['proposals','Proponer'],['direct','Cambios directos']].map(([v,l])=>`<option value="${v}" ${a.mode===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Alcance<select name="scene_id"><option value="">Proyecto</option>${scenes().map(s=>`<option value="${esc(s.id)}" ${a.scene_id===s.id?'selected':''}>${esc(title(s))}</option>`).join('')}</select></label>${button('set-autonomy','Guardar alcance','data-story-mutate')}</form><p class="hint">${esc(a.execution||'La preparación queda guardada. Sin ejecutor activo, espera reanudación.')}</p><h3>Propuestas</h3>${rows('proposals').filter(p=>['pending','partial','conflict'].includes(p.status)).map(p=>button('proposal',esc(p.title),`data-proposal="${esc(p.id)}"`)).join('')||'<p class="hint">Sin propuestas pendientes</p>'}<h3>Cola</h3>${rows('tasks').map(t=>`<div class="story-work-item"><strong>${esc(t.title)}</strong><small>${esc(status(t.status))}</small>${t.detail?`<p>${esc(t.detail)}</p>`:''}${!['complete','cancelled'].includes(t.status)?button('cancel-task','Cancelar',`data-task="${esc(t.id)}" data-story-mutate`):''}</div>`).join('')||'<p class="hint">Sin tareas pendientes</p>'}`,`${button('prepare-task','Preparar siguiente trabajo','data-story-mutate')}${button('run-preparation','Procesar preparación pendiente','class="primary" data-story-mutate')}`),'work');}
 function projectDialog(){const p=S.data.project,d=draft('project',p);S.dialogEntity={type:'project',entity:p,isNew:false};dialog(formShell('Historia y criterios',`<form id="story-entity-form">${[['title','Título'],['description','Descripción'],['synopsis','Sinopsis'],['treatment','Tratamiento'],['tone','Tono e intención'],['visual_style','Criterios visuales'],['format','Formato'],['target_duration_sec','Duración objetivo · segundos']].map(([k,l])=>field(k,l,d.values[k]||'',!['title','format','target_duration_sec'].includes(k),k==='target_duration_sec'?'type="number" min="0.1" step="any"':'')).join('')}</form>`,button('save-project','Guardar','class="primary" data-story-mutate')),'project');document.querySelectorAll('#story-entity-form input,#story-entity-form textarea').forEach(input=>input.addEventListener('input',saveEntityDraft));}
 function continuityDialog(){dialog(formShell('Personajes y continuidad',`<div class="story-continuity-list">${rows('elements').map(e=>`<div class="story-asset-use"><button class="story-text-button" data-story="edit-element" data-element="${esc(e.id)}"><strong>${esc(e.name)}</strong><small>${esc(kind(e.kind))}</small><p>${esc(e.description||'')}</p></button>${button('element-reference','Referencias',`data-element="${esc(e.id)}"`)}</div>`).join('')}</div>${button('new-element','+ Personaje o elemento')}<h3>Indicaciones visibles</h3>${rows('preferences').map(p=>`<div class="story-asset-use"><button class="story-text-button" data-story="edit-preference" data-preference="${esc(p.id)}"><small>${esc(scopeName(p.scope))} · ${p.enabled===false?'Desactivada':'Activa'}</small><p>${esc(p.text)}</p></button></div>`).join('')||'<p class="hint">No hay reglas ocultas. Guarda aquí las correcciones que quieras conservar.</p>'}${button('new-preference','+ Indicación')}`),'continuity');}
 function elementDialog(id=null){const e=rows('elements').find(e=>e.id===id)||{id:'new:'+rid(),revision:0,kind:'character'},d=draft('element',e);S.element=e;dialog(formShell(id?'Editar continuidad':'Añadir personaje o elemento',`<form id="story-element-form"><label>Tipo<select name="kind" ${id?'disabled':''}>${['character','location','costume','object','continuity'].map(k=>`<option value="${k}" ${d.values.kind===k?'selected':''}>${kind(k)}</option>`).join('')}</select></label>${field('name','Nombre',d.values.name)}${field('description','Descripción y continuidad',d.values.description,true)}${field('variants','Variantes de apariencia · una por línea',(d.values.variants||[]).join('\n'),true)}${field('notes','Notas de representación',d.values.notes,true)}<label>Escena · opcional<select name="scene_id"><option value="">General</option>${scenes().map(s=>`<option value="${esc(s.id)}" ${d.values.scene_id===s.id?'selected':''}>${esc(title(s))}</option>`).join('')}</select></label><label>Personaje relacionado · opcional<select name="character_id"><option value="">Ninguno</option>${rows('elements').filter(x=>x.kind==='character').map(c=>`<option value="${esc(c.id)}" ${d.values.character_id===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label></form>`,button('save-element','Guardar','class="primary" data-story-mutate')),'element');document.querySelectorAll('#story-element-form input,#story-element-form textarea,#story-element-form select').forEach(input=>input.addEventListener('input',()=>{const fields=Object.fromEntries(new FormData(document.querySelector('#story-element-form')));Object.assign(d.values,fields);d.values.variants=String(fields.variants||'').split('\n').filter(Boolean);d.dirty=true;d.operation=rid();persistDrafts();}));}
 function preferenceDialog(id=null){const p=rows('preferences').find(p=>p.id===id)||{id:'new:'+rid(),revision:0,scope:'project',target_id:S.projectId,text:'',enabled:true};S.preference=p;dialog(formShell('Indicación del proyecto',`<form id="story-preference-form">${field('text','Corrección explícita que quieres conservar',p.text,true)}<label>Alcance<select name="target">${[[`project:${S.projectId}`,'Proyecto'],...scenes().map(s=>[`scene:${s.id}`,title(s)]),...shots().map(s=>[`shot:${s.id}`,title(s)]),...rows('elements').filter(e=>e.kind==='character').map(c=>[`character:${c.id}`,c.name])].map(([value,label])=>`<option value="${esc(value)}" ${`${p.scope}:${p.target_id}`===value?'selected':''}>${esc(label)}</option>`).join('')}</select></label><label class="story-check"><input type="checkbox" name="enabled" ${p.enabled!==false?'checked':''}>Aplicar esta indicación</label></form>`,button('save-preference','Guardar','class="primary" data-story-mutate')),'preference');}
 function preserveDialog(){dialog(formShell('Planos que el agente debe conservar',`<p class="hint">Se respetan dentro del alcance de tu orden.</p>${shots().filter(s=>S.scope==='project'||s.scene_id===S.sceneId).map(s=>`<label class="story-check"><input type="checkbox" data-story-preserve="${esc(s.id)}" ${S.preserve.has(s.id)?'checked':''}>${esc(title(s))}</label>`).join('')}`,button('save-preserve','Listo','class="primary"')),'preserve');}
 function importScriptDialog(){const id=`${S.projectId}:import`,d=drafts[id]||(drafts[id]={values:{title:'Guion importado',text:''},operation:rid()});dialog(formShell('Importar guion',`<p class="hint">Pega el texto o abre un TXT o Markdown. Se conservará como bloques editables sin exigir una sintaxis especial.</p><form id="story-import-script-form">${field('title','Escena de entrada',d.values.title)}${field('text','Guion',d.values.text,true)}<input type="file" id="story-script-file" accept=".txt,.md,text/plain,text/markdown"></form>`,button('apply-script','Importar','class="primary" data-story-mutate')),'import-script');document.querySelectorAll('#story-import-script-form input:not([type=file]),#story-import-script-form textarea').forEach(input=>input.addEventListener('input',()=>{d.values=Object.fromEntries(new FormData(document.querySelector('#story-import-script-form')));delete d.values.file;d.operation=rid();persistDrafts();}));}
 function compareDialog(type,entity){const d=draft(type,entity),fields=Object.keys(d.values).filter(key=>labels[key]&&JSON.stringify(d.values[key])!==JSON.stringify(entity[key]));dialog(formShell('Comparar edición reciente',`${fields.map(field=>`<div class="story-diff-field"><strong>${labels[field]}</strong><div class="story-diff-old"><small>Actual</small><p>${esc(prettyValue(field,entity[field]))}</p></div><div class="story-diff-new"><small>Tu borrador</small><p>${esc(prettyValue(field,d.values[field]))}</p></div></div>`).join('')||'<p>El contenido coincide; cambió su revisión.</p>'}`,`${button('discard-conflict','Usar versión actual',`data-type="${type}" data-id="${esc(entity.id)}"`)}${button('rebase-conflict','Conservar mi edición tras comparar',`data-type="${type}" data-id="${esc(entity.id)}" class="primary"`)}`),'compare');}
 async function importMaterial(files){for(const file of files){const imported=await NexusImports.importFile(file);await rpc('libraryImport',{id:imported.id,projectId:S.projectId});}const snapshot=await call('storySelection',{});if(snapshot.index)Agent.snapshot.index=snapshot.index;await load();window.dispatchEvent(new CustomEvent('nexus:library-changed'));toast(`${files.length} archivos guardados en Por colocar.`);}
 const beforeRender=render;
 render=function(){if(view==='story'){window.NexusFlowLive?.stop();renderShell();$('#content').classList.remove('agent-view','canvas-view','studio-library');paintStory();if(!S.data&&!S.loading&&!S.error)load();}else{$('#content').classList.remove('story-view');beforeRender();}decorateNav();};
 function decorateNav(){const nav=$('#navigation');if(!nav)return;const primary=[['assistant','Agente'],['canvas','ArtBox'],['story','Guion'],['library','Biblioteca'],['flow','Flow'],['editor','Montaje']];const ordered=[];for(const[id,label]of primary){let entry=nav.querySelector(`[data-nav="${id}"]`);if(!entry){entry=document.createElement('button');entry.dataset.nav=id;nav.append(entry);}const glyph=id==='assistant'?aiIcon('chat'):id==='story'?'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M5 3h11l3 3v15H5zM9 8h6M9 12h6M9 16h4"/></svg>':icon(id);entry.innerHTML=glyph+label;entry.classList.toggle('active',view===id||id==='canvas'&&view==='catalog');entry.setAttribute('aria-label',label);entry.setAttribute('aria-current',view===id?'page':'false');entry.title=label;ordered.push(entry);}for(const entry of ordered.reverse())nav.prepend(entry);}
 const beforeAssistant=renderAssistant;renderAssistant=function(){beforeAssistant();decorateAgentContext();};
 document.addEventListener('click',async event=>{const target=event.target.closest('[data-story],[data-story-tab],[data-story-scene],[data-story-edit],[data-story-insert],[data-story-asset],[data-story-link-asset]');if(!target)return;event.preventDefault();
  try{
   if(target.dataset.storyTab){S.tab=target.dataset.storyTab;S.limit=80;persist();paintStory();return;}
   if(target.dataset.storyScene){S.sceneId=target.dataset.storyScene;S.shotId=null;S.limit=80;persist();await load();return;}
   if(target.dataset.storyAsset){assetDialog(target.dataset.storyAsset);return;}
   if(target.dataset.storyLinkAsset){S.linkAsset=target.dataset.storyLinkAsset;document.querySelectorAll('[data-story-link-asset]').forEach(node=>node.classList.toggle('is-selected',node===target));return;}
   if(target.dataset.storyInsert){const kind=target.dataset.storyInsert;if(kind==='shot')entityForm('shot',null,Number(target.dataset.storyOrder));else{const result=await mutate({action:'create_block',scene_id:S.sceneId,kind,order:Number(target.dataset.storyOrder),text:''});const created=blocks().find(b=>b.id===result.id);if(created)entityForm('block',created);}return;}
   if(target.dataset.storyEdit){const [type,id]=target.dataset.storyEdit.split(':');const entity=(type==='shot'?shots():type==='scene'?scenes():blocks()).find(x=>x.id===id);if(type==='shot'){S.shotId=id;await load(S.projectId,{paint:false});}entityForm(type,entity);return;}
   const action=target.dataset.story,shot=shots().find(s=>s.id===target.dataset.shot),block=blocks().find(b=>b.id===target.dataset.block),scene=scenes().find(s=>s.id===S.sceneId);
   switch(action){
    case'close-dialog':closeDialog();break;
    case'new-project':dialog(formShell('Nuevo proyecto',`<form id="story-new-project-form">${field('name','Nombre del proyecto','','', 'required')}</form>`,button('create-project','Crear','class="primary"')),'new-project');break;
    case'create-project':{const name=document.querySelector('#story-new-project-form [name=name]').value.trim();if(!name)throw Error('Escribe un nombre.');await agentCall('createProject',{name});S.projectId=Agent.snapshot.projectId;S.sceneId=null;closeDialog();await load();break;}
    case'new-scene':entityForm('scene');break;
    case'edit-scene':if(scene)entityForm('scene',scene);break;
    case'new-shot':if(!S.sceneId)throw Error('Crea una escena primero.');entityForm('shot');break;
    case'save-block':if(block){const d=draft('block',block);await mutate({action:'update_block',block_id:block.id,text:d.values.text,speaker:d.values.speaker||null},{draftType:'block',draftEntity:block});}break;
    case'block-detail':if(block)entityForm('block',block);break;
    case'compare-block':if(block)compareDialog('block',block);break;
    case'compare-dialog':if(S.dialogEntity){const {type,entity}=S.dialogEntity;compareDialog(type,allEntities().find(x=>x.id===entity.id)||entity);}break;
    case'discard-conflict':{const type=target.dataset.type,id=target.dataset.id;discardDraft(type,id);closeDialog();paintStory();break;}
    case'rebase-conflict':{const type=target.dataset.type,item=allEntities().find(x=>x.id===target.dataset.id);if(!item)throw Error('El contenido ya no está en la estructura.');const d=draft(type,item);d.base=item.revision;d.operation=rid();persistDrafts();closeDialog();if(type==='block')paintStory();else entityForm(type,item);break;}
    case'save-entity':{saveEntityDraft();const {type,entity,isNew,order}=S.dialogEntity,d=draft(type,entity),fields={...d.values};for(const k of ['id','project_id','revision','content_revision','variant_of','code','kind','shot_id','order'])delete fields[k];if(type==='block')for(const k of Object.keys(fields))if(!['text','speaker','narrative_state','scene_id'].includes(k))delete fields[k];if(type==='shot'&&fields.duration_sec==='')fields.duration_sec=null;const input={action:(isNew?'create_':'update_')+type,...fields,...(!isNew?{[type+'_id']:entity.id}:{}),...(order!=null?{[type==='shot'?'block_order':'order']:order}:{})};await mutate(input,{draftType:type,draftEntity:entity});break;}
    case'delete-entity':{const {type,entity}=S.dialogEntity;if(!confirm(`¿Retirar ${type==='shot'?'el plano':type==='scene'?'la escena':'el fragmento'}? Sus archivos se conservarán.`))return;await mutate({action:'delete_'+type,[type+'_id']:entity.id,expected_revision:entity.revision});break;}
    case'duplicate-entity':{const {entity}=S.dialogEntity;await mutate({action:'duplicate_shot',shot_id:entity.id,expected_revision:entity.revision});break;}
    case'move-block':if(block)await mutate({action:'move_block',block_id:block.id,scene_id:block.scene_id,order:block.order+Number(target.dataset.delta),expected_revision:block.revision});break;
    case'move-shot':if(shot)await mutate({action:'move_shot',shot_id:shot.id,scene_id:shot.scene_id,order:shot.order+Number(target.dataset.delta),expected_revision:shot.revision});break;
    case'move-scene':if(scene)await mutate({action:'move_scene',scene_id:scene.id,order:scene.order+Number(target.dataset.delta),expected_revision:scene.revision});break;
    case'project':projectDialog();break;
    case'save-project':{saveEntityDraft();const p=S.data.project,d=draft('project',p),fields={};for(const field of ['title','description','synopsis','treatment','tone','visual_style','format','target_duration_sec'])fields[field]=field==='target_duration_sec'?(d.values[field]?Number(d.values[field]):null):d.values[field]||'';await mutate({action:'update_project',...fields},{draftType:'project',draftEntity:p});break;}
    case'continuity':continuityDialog();break;
    case'new-element':elementDialog();break;
    case'edit-element':elementDialog(target.dataset.element);break;
    case'save-element':{const e=S.element,d=draft('element',e),fields=Object.fromEntries(new FormData(document.querySelector('#story-element-form')));fields.kind=fields.kind||e.kind;fields.variants=String(fields.variants||'').split('\n').filter(Boolean);if(!fields.name?.trim())throw Error('Escribe un nombre.');if(fields.kind==='character'){delete fields.scene_id;delete fields.character_id;}else{delete fields.variants;delete fields.notes;}await mutate({action:'upsert_element',...fields,...(!e.id.startsWith('new:')?{element_id:e.id,expected_revision:e.revision}:{})},{draftType:'element',draftEntity:e});break;}
    case'element-reference':{const e=rows('elements').find(x=>x.id===target.dataset.element);linkDialog(e.kind==='character'?'character':'element',e.id);break;}
    case'new-preference':preferenceDialog();break;
    case'edit-preference':preferenceDialog(target.dataset.preference);break;
    case'save-preference':{const p=S.preference,form=document.querySelector('#story-preference-form'),fields=Object.fromEntries(new FormData(form)),[scope,id]=fields.target.split(':');await mutate({action:'set_preference',scope,target_id:id,text:fields.text,enabled:form.elements.enabled.checked,...(!p.id.startsWith('new:')?{preference_id:p.id,expected_revision:p.revision}:{})});break;}
    case'shot-material':if(shot){S.shotId=shot.id;persist();linkDialog('shot',shot.id);}break;
    case'block-material':if(block)linkDialog('block',block.id);break;
    case'scene-material':linkDialog('scene',S.sceneId);break;
    case'entity-material':{const {type,entity}=S.dialogEntity;linkDialog(type,entity.id);break;}
    case'reuse-material':linkDialog(S.shotId?'shot':S.sceneId?'scene':'project',S.shotId||S.sceneId||S.projectId,target.dataset.asset);break;
    case'apply-link':{if(!S.linkAsset)throw Error('Selecciona un archivo.');const form=document.querySelector('#story-link-form'),fields=Object.fromEntries(new FormData(form));if(['identity','costume'].includes(fields.role)&&!fields.character_id)throw Error('Elige el personaje al que corresponde.');if(!fields.character_id)delete fields.character_id;await mutate({action:'link_material',...fields,asset_id:S.linkAsset,scope:S.linkTarget.scope,target_id:S.linkTarget.targetId,selected:form.elements.selected.checked});break;}
    case'unlink':await mutate({action:'unlink_material',link_id:target.dataset.link,expected_revision:Number(target.dataset.revision)});break;
    case'agent':await selectContext({shotId:shot?.id||null,blockId:block?.id||null});break;
    case'generate':{if(!shot)throw Error('Selecciona un plano.');await selectContext({shotId:shot.id,navigateAgent:false});const prepared=await mutate({action:'prepare_generation',shot_id:shot.id,scene_id:shot.scene_id});if(!window.NexusStoryGeneration?.prepare)throw Error('La conexión de ArtBox con el plano no está disponible en esta versión.');await NexusStoryGeneration.prepare(prepared.context);navigate('canvas');break;}
    case'flow':{if(!shot)throw Error('Selecciona un plano.');await selectContext({shotId:shot.id,navigateAgent:false});navigate('flow');break;}
    case'preserve':preserveDialog();break;
    case'save-preserve':S.preserve=new Set([...document.querySelectorAll('[data-story-preserve]:checked')].map(node=>node.dataset.storyPreserve));persist();closeDialog();paintStory();break;
    case'work':workDialog();break;
    case'proposal':proposalDialog(target.dataset.proposal);break;
    case'apply-proposal':{const p=rows('proposals').find(p=>p.id===S.proposalId),ids=[...document.querySelectorAll('[data-story-change]:checked')].map(node=>node.dataset.storyChange);if(!ids.length)throw Error('Selecciona algún cambio.');await mutate({action:'apply_proposal',proposal_id:p.id,expected_revision:p.revision,change_ids:ids});break;}
    case'reject-proposal':{const p=rows('proposals').find(p=>p.id===S.proposalId);await mutate({action:'reject_proposal',proposal_id:p.id,expected_revision:p.revision});break;}
    case'set-autonomy':{const form=document.querySelector('#story-autonomy-form'),fields=Object.fromEntries(new FormData(form));await mutate({action:'set_autonomy',...fields,scene_id:fields.scene_id||null,enabled:form.elements.enabled.checked,expected_revision:S.data.autonomy.revision});break;}
    case'prepare-task':await mutate({action:'enqueue_task',kind:'preparation',title:'Revisar planos y material pendiente',scene_id:S.sceneId});break;
    case'run-preparation':await mutate({action:'run_preparation'});break;
    case'cancel-task':{const t=rows('tasks').find(t=>t.id===target.dataset.task);await mutate({action:'update_task',task_id:t.id,expected_revision:t.revision,status:'cancelled'});break;}
    case'import-script':importScriptDialog();break;
    case'apply-script':{const d=drafts[`${S.projectId}:import`],fields=Object.fromEntries(new FormData(document.querySelector('#story-import-script-form')));if(!fields.text?.trim())throw Error('Escribe o abre un guion.');await mutate({action:'import_script',operation_id:d.operation,title:fields.title,text:fields.text});delete drafts[`${S.projectId}:import`];persistDrafts();break;}
    case'import-material':document.querySelector('#story-media-picker')?.click();break;
    case'undo':await mutate({action:'undo'});break;
    case'refresh':await load();break;
    case'more':S.limit+=80;paintStory();break;
    case'return-story':navigate('story');break;
    case'clear-context':await call('storySelection',{projectId:null});S.selection=null;decorateAgentContext();break;
   }
  }catch(error){const node=document.querySelector('#story-dialog-error');if(node)node.textContent=error.message;else toast(error.message);}
 });
 document.addEventListener('input',event=>{const input=event.target;if(input.dataset.storyBlockField){const block=blocks().find(b=>b.id===input.dataset.id);if(block){const d=writeDraft('block',block,input.dataset.storyBlockField,input.value);d.dirty=true;persistDrafts();const note=input.closest('.story-block').querySelector('.story-draft-note');if(note&&!stale('block',block))note.textContent='Borrador guardado en este PC';}return;}if(input.id==='story-link-search'){const query=input.value.toLocaleLowerCase();document.querySelectorAll('[data-story-link-asset]').forEach(node=>node.hidden=!node.dataset.name.includes(query));}if(input.id==='story-material-search'){S.query=input.value;const pos=input.selectionStart;paintStory();const next=$('#story-material-search');next?.focus();next?.setSelectionRange(pos,pos);}});
 document.addEventListener('change',async event=>{const input=event.target;try{if(input.id==='story-project'){if(!input.value)return;await agentCall('project',{id:input.value});S.sceneId=null;S.shotId=null;await load(input.value);}if(input.id==='story-material-scope'){S.materialScope=input.value;paintStory();}if(input.id==='story-material-type'){S.type=input.value;paintStory();}if(input.id==='story-material-inbox'){S.inbox=input.checked;paintStory();}if(input.id==='story-material-chosen'){S.chosen=input.checked;paintStory();}if(input.id==='story-agent-mode'){S.mode=input.value;persist();}if(input.id==='story-agent-scope'){S.scope=input.value;persist();}if(input.id==='story-media-picker'&&input.files.length)await importMaterial([...input.files]);if(input.id==='story-script-file'&&input.files[0]){const text=await input.files[0].text();const textarea=document.querySelector('#story-import-script-form [name=text]');textarea.value=text;textarea.dispatchEvent(new Event('input',{bubbles:true}));}}catch(error){const node=document.querySelector('#story-dialog-error');if(node)node.textContent=error.message;else toast(error.message);}});
 document.addEventListener('keydown',event=>{if(event.ctrlKey&&event.key==='Enter'&&event.target.dataset.storyBlockField){event.preventDefault();event.target.closest('.story-block').querySelector('[data-story=save-block]')?.click();}});
 document.addEventListener('submit',event=>{if(!event.target.id.startsWith('story-'))return;event.preventDefault();const action=({'story-new-project-form':'create-project','story-entity-form':S.dialog==='project'?'save-project':'save-entity','story-element-form':'save-element','story-preference-form':'save-preference','story-import-script-form':'apply-script'})[event.target.id];if(action)document.querySelector(`#story-dialog [data-story="${action}"]`)?.click();});
 document.addEventListener('dragover',event=>{if(view==='story'&&S.tab==='material'&&event.dataTransfer?.types.includes('Files'))event.preventDefault();});
 document.addEventListener('drop',event=>{if(view==='story'&&S.tab==='material'&&event.dataTransfer?.files.length){event.preventDefault();importMaterial([...event.dataTransfer.files]).catch(error=>toast(error.message));}});
 setInterval(async()=>{if(view!=='story'||!S.projectId||S.busy||S.loading)return;const focused=document.activeElement?.matches('textarea,input,select')||!!S.dialog;await load(S.projectId,{paint:!focused});if(focused){const node=document.querySelector('[data-story-status]');if(node)node.textContent='Contexto actualizado · tu borrador se conserva';}},4000);
 window.NexusStory={load,render:paintStory,state:S,select:selectContext};
})();
